import { fireEvent, render } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import type { ConversationData, ConversationTurn, FeatureResult, QuestionActionState, QuestionQueueData, TurnView } from "../../surface/types";
import { ConversationDrawer } from "./ConversationDrawer";

const questions: QuestionQueueData = { queue: [], count: 0, meta: { total: 0, tail: null, pending: null, invite: "", answeredByDocument: "" } };
const turn = (more: Partial<ConversationTurn> = {}): ConversationTurn => ({ id: "turn-1", kind: "ask", occurredAt: "2026-08-29", prompt: "What changed?", said: "", questionId: "", outcome: "completed", message: "", reason: "", answer: null, proposal: null, ...more });
const ready = (data: ConversationData): FeatureResult<ConversationData> => ({ state: "ready", data });
const controls = { state: { state: "idle" } as const, onAnswer: vi.fn(), onConfirm: vi.fn(), onDecline: vi.fn() };
const openFigure = vi.fn();

describe("durable Viva conversation", () => {
  it("shows a conversation boundary and starts the next question independently", () => {
    const onAsk = vi.fn();
    const onNewConversation = vi.fn();
    const props = { result: ready({ turns: [turn({ contextMode: "new_question" })], questions }), selectedQueue: "", onSelectQueue: vi.fn(), onOpenFigure: openFigure, ask: { state: { state: "idle" } as const, onAsk }, controls };
    const view = render(<ConversationDrawer {...props} context={{ mode: "follow_up", onNewConversation }} />);
    expect(view.getByText("Continuing this conversation")).toBeInTheDocument();
    expect(view.getByText("New question", { selector: ".conversation-turn-meta span" })).toBeInTheDocument();
    fireEvent.change(view.getByLabelText("Your question"), { target: { value: "And then?" } });
    fireEvent.click(view.getByRole("button", { name: "Ask" }));
    expect(onAsk).toHaveBeenCalledWith("And then?", true, false, "follow_up");
    fireEvent.click(view.getByRole("button", { name: "New conversation" }));
    expect(onNewConversation).toHaveBeenCalledOnce();
    view.rerender(<ConversationDrawer {...props} context={{ mode: "new_question", onNewConversation }} />);
    expect(view.getByText("Earlier messages stay saved. Your next question will not use them.")).toBeInTheDocument();
    fireEvent.click(view.getByRole("button", { name: "Ask" }));
    expect(onAsk).toHaveBeenLastCalledWith("And then?", true, false, "new_question");
  });

  it("fills an editable starter without submitting and guards New conversation during a request", () => {
    const onAsk = vi.fn(), onNewConversation = vi.fn();
    const props = { result: ready({ turns: [], questions }), selectedQueue: "", onSelectQueue: vi.fn(), onOpenFigure: openFigure, controls, starterQuestions: ["What is excluded from my net worth?"], context: { mode: "new_question" as const, onNewConversation } };
    const view = render(<ConversationDrawer {...props} ask={{ state: { state: "idle" }, onAsk }} />);
    fireEvent.click(view.getByRole("button", { name: "What is excluded from my net worth?" }));
    expect(view.getByLabelText("Your question")).toHaveValue("What is excluded from my net worth?");
    expect(view.getByLabelText("Your question")).toHaveFocus();
    expect(onAsk).not.toHaveBeenCalled();
    view.rerender(<ConversationDrawer {...props} ask={{ state: { state: "working", question: "A question" }, onAsk }} />);
    fireEvent.click(view.getByRole("button", { name: "New conversation" }));
    expect(onNewConversation).not.toHaveBeenCalled();
  });
  it("renders the persisted timeline and the deterministic question queue together", () => {
    const data: ConversationData = { turns: [turn({ message: "The records changed." })], questions: { ...questions, queue: [{ id: "q-1", label: "What was this payment?", detail: "It is not classified.", status: "", action: "", type: "nature", evidence: "", state: "needs_input", outcome: null, disposition: null }] } };
    const view = render(<ConversationDrawer result={ready(data)} selectedQueue="q-1" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={controls} />);
    expect(view.getByText("Conversation")).toBeInTheDocument();
    expect(view.getByText("What changed?")).toBeInTheDocument();
    expect(view.getAllByText("What was this payment?").length).toBeGreaterThan(0);
  });

  it("keeps each durable outcome distinct and preserves the reviewed receipt detail", () => {
    const answer: TurnView = {
      question: "What changed?",
      text: "Your balance changed.",
      answered: true,
      status: "answered", outcomeTag: "", options: [], missing: [],
      refusal: "",
      grade: "verified",
      gradeSentence: "The source records verify this figure.",
      figures: [{ id: "figure-opaque", evidenceId: "conversation:turn-1:figure-opaque", written: "USD 20.00", grade: "verified", what: "The balance change", recordIds: ["record-secret-1"], evidenceLinks: [{ targetDocumentId: "doc-1", label: "Checking statement", relation: "attests", page: "" }] }],
      spoken: { maySpeak: true, withheld: "", parts: [], text: "", gradeSentence: "", citationSentence: "One local record supports this figure.", localOnly: "" },
    };
    const turns = [
      turn({ id: "completed", answer }),
      turn({ id: "refused", outcome: "refused", message: "I could not answer from these records." }),
      turn({ id: "waiting", outcome: "waiting", message: "A statement settles this." }),
      turn({ id: "stale", outcome: "stale", message: "The question changed before confirmation." }),
      turn({ id: "set-aside", outcome: "set_aside", message: "Set aside until the subject changes." }),
    ];
    const onOpenFigure = vi.fn();
    const view = render(<ConversationDrawer result={ready({ turns, questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={onOpenFigure} ask={null} controls={controls} />);

    for (const label of ["Completed", "Not completed", "Waiting", "Out of date", "Set aside"]) expect(view.getByText(label)).toBeInTheDocument();
    expect(view.getByText("The source records verify this figure.")).toBeInTheDocument();
    expect(view.getByText("One local record supports this figure.")).toBeInTheDocument();
    expect(view.getByText(/1 cited record/)).toBeInTheDocument();
    expect(view.container).not.toHaveTextContent("record-secret-1");
    const receipt = view.getByRole("button", { name: "USD 20.00 The balance change", description: "View evidence for The balance change" });
    expect(receipt).toHaveAttribute("aria-haspopup", "dialog");
    expect(receipt).toHaveAttribute("aria-controls", "figure-evidence-drawer");
    fireEvent.click(receipt);
    expect(onOpenFigure).toHaveBeenCalledWith("conversation:turn-1:figure-opaque");
  });

  it("confirms a persisted proposal by its opaque identity", () => {
    const proposed = turn({ kind: "answer", questionId: "q-1", proposal: { id: "p-1", summary: "Record the account as Home loan.", status: "open", outcome: "proposal", message: "", reason: "" } });
    const onConfirm = vi.fn();
    const view = render(<ConversationDrawer result={ready({ turns: [proposed], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={{ ...controls, onConfirm }} />);
    fireEvent.change(view.getByLabelText("Confirm or decline in your own words"), { target: { value: "yes, that is right" } });
    fireEvent.click(view.getByRole("button", { name: "Reply" }));
    expect(onConfirm).toHaveBeenCalledWith("q-1", "p-1", "yes, that is right", "Record the account as Home loan.");
  });

  it("renders one confirmation path and one action receipt when a proposal is restored", () => {
    const proposed = turn({ kind: "answer", questionId: "q-1", outcome: "proposal", proposal: { id: "p-1", summary: "Record the account as Home loan.", status: "open", outcome: "proposal", message: "", reason: "" } });
    const state: QuestionActionState = { state: "settled", questionId: "q-1", verb: "answer", result: { state: "settled", outcome: { kind: "proposal", message: "Nothing was recorded.", reason: "", proposalId: "p-1", proposalSummary: "Record the account as Home loan." } } };
    const view = render(<ConversationDrawer result={ready({ turns: [proposed], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={{ ...controls, state }} />);

    expect(view.getByLabelText("Confirm or decline in your own words")).toBeInTheDocument();
    expect(view.queryByRole("button", { name: "Confirm this proposal" })).not.toBeInTheDocument();
    expect(view.queryByRole("button", { name: "Decline this proposal" })).not.toBeInTheDocument();
    expect(view.getAllByText("Held for your confirmation")).toHaveLength(1);
  });

  it("keeps a settled action receipt when the conversation reread fails", () => {
    const state: QuestionActionState = { state: "settled", questionId: "q-1", verb: "decline", result: { state: "settled", outcome: { kind: "set_aside", message: "Set aside until the subject changes.", reason: "" } } };
    const view = render(<ConversationDrawer result={{ state: "failed", reason: "read_failed" }} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={{ ...controls, state }} />);

    expect(view.getByText("Conversation could not be loaded")).toBeInTheDocument();
    expect(view.getAllByText("Question set aside")).toHaveLength(1);
    expect(view.getByText("Set aside until the subject changes.")).toBeInTheDocument();
  });

  it("shows an empty durable history without inventing a transcript", () => {
    const view = render(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={controls} />);
    expect(view.getByText("No conversation yet")).toBeInTheDocument();
    expect(view.queryByText(/supplied conversation/i)).not.toBeInTheDocument();
  });

  it("invites only Ask when Review questions are outside this view", () => {
    const view = render(<ConversationDrawer mode="ask" result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={{ state: { state: "idle" }, onAsk: vi.fn() }} controls={controls} />);
    expect(view.getByText("Ask Viva about your money. Your questions and answers stay saved in this vault.")).toBeVisible();
    expect(view.queryByText(/questions below/)).not.toBeInTheDocument();
  });

  it("routes the same conversational draft to Plans for review", () => {
    const onReviewPlan = vi.fn();
    const goalDraft = {
      kind: "ready", message: "Draft ready. Nothing was recorded.",
      reason: "", verb: "create", reviewInPlans: true,
      draft: {
        verb: "create",
        payload: { title: "Trip", currency: "USD", target_amount: "600" },
        calculated: { reserved: "0", remaining: "600", required_monthly: "100", projected_completion_date: "2027-02-28", status: "on_track" },
      },
    } as const;
    const answer: TurnView = {
      question: "Make a savings goal", text: goalDraft.message,
      answered: true, status: "answered", outcomeTag: "", options: [], missing: [], refusal: "", grade: "", gradeSentence: "",
      figures: [], spoken: { maySpeak: true, withheld: "", parts: [], text: goalDraft.message, gradeSentence: "", citationSentence: "", localOnly: "" },
      goalDraft,
    };
    const view = render(<ConversationDrawer result={ready({ turns: [turn({ answer })], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} onReviewPlan={onReviewPlan} ask={null} controls={controls} />);

    fireEvent.click(view.getByRole("button", { name: "Review in Plans" }));
    expect(onReviewPlan).toHaveBeenCalledWith(goalDraft);
  });

  it("uses an explicit plan gesture instead of guessing from the question's words", () => {
    const onAsk = vi.fn();
    const view = render(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={{ state: { state: "idle" }, onAsk }} controls={controls} />);

    fireEvent.change(view.getByLabelText("Your question"), { target: { value: "Build a rainy-day fund" } });
    fireEvent.click(view.getByText("Plan a savings goal"));
    fireEvent.click(view.getByRole("button", { name: "Draft a save-up plan" }));

    expect(onAsk).toHaveBeenCalledWith("Build a rainy-day fund", true, true, "new_question");
  });

  it("keeps an Ask Viva draft through failure and clears only its own authoritative completion", () => {
    const onAsk = vi.fn();
    const idle = { state: { state: "idle" } as const, onAsk };
    const working = { state: { state: "working", question: "What changed?" } as const, onAsk };
    const failed = { state: { state: "settled", question: "What changed?", authoritative: false,
      result: { state: "unanswered" }, turn: null } as const, onAsk };
    const completed = { state: { state: "settled", question: "What changed?", authoritative: true,
      result: { state: "settled", outcome: { kind: "completed", message: "Answered.", reason: "" } }, turn: null } as const, onAsk };
    const view = render(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={idle} controls={controls} />);
    const box = () => view.getByLabelText("Your question");

    fireEvent.change(box(), { target: { value: "What changed?" } });
    fireEvent.click(view.getByRole("button", { name: "Ask" }));
    expect(box()).toHaveValue("What changed?");
    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={working} controls={controls} />);
    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={failed} controls={controls} />);
    expect(box()).toHaveValue("What changed?");

    fireEvent.change(box(), { target: { value: "What changed since Monday?" } });
    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={completed} controls={controls} />);
    expect(box()).toHaveValue("What changed since Monday?");

    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={idle} controls={controls} />);
    fireEvent.change(box(), { target: { value: "What changed?" } });
    fireEvent.click(view.getByRole("button", { name: "Ask" }));
    // The old settled state is no longer enough; the matching working state must be observed.
    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={working} controls={controls} />);
    view.rerender(<ConversationDrawer result={ready({ turns: [], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={completed} controls={controls} />);
    expect(box()).toHaveValue("");
  });

  it("announces one plain capability boundary after Ask settles", () => {
    const text = "I cannot answer that financial question yet. The available financial answers are listed below.";
    const answer: TurnView = {
      question: "Forecast next year", text, answered: false,
      status: "capability_gap", outcomeTag: "unsupported_family",
      refusal: "unsupported_family", grade: "", gradeSentence: "",
      figures: [], options: [], spoken: { maySpeak: false, withheld: "", parts: [], text: "", gradeSentence: "", citationSentence: "", localOnly: "" },
      missing: [{ tag: "unsupported_family", label: "What is available", question: "",
        requestedFamily: "future_projection", requestedLabel: "a financial answer that is not available yet",
        supportedFamilies: [
          { id: "named_account_balance", label: "one account's balance", example: "the balance and date for one named account" },
          { id: "net_worth", label: "net worth and exclusions", example: "net worth by currency and what is excluded" },
        ] }],
    };
    const asked = turn({ answer, prompt: answer.question });
    const ask = { state: { state: "settled", question: answer.question,
      result: { state: "settled", outcome: { kind: "completed", message: "", reason: "" } }, turn: answer } as const, onAsk: vi.fn() };
    const view = render(<ConversationDrawer result={ready({ turns: [asked], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={ask} controls={controls} />);

    expect(view.getAllByText(text)).toHaveLength(1);
    const announced = view.getAllByRole("status").find((node) => node.textContent?.includes(text));
    expect(announced).toHaveAttribute("aria-live", "polite");
    expect(announced).toHaveAttribute("aria-atomic", "true");
    const detail = view.getByLabelText("Available financial answers");
    expect(detail).toHaveTextContent("Requested a financial answer that is not available yet");
    expect(detail).toHaveTextContent("Available now");
    expect(detail).toHaveTextContent("one account's balance");
    expect(detail).toHaveTextContent("the balance and date for one named account");
    expect(view.container).not.toHaveTextContent("future_projection");
    expect(view.container).not.toHaveTextContent("named_account_balance");
  });
});

