it("renders every selected uncertainty readably while preserving figures and source actions on replay", () => {
  const answer = selected_answer;
  const saved = structuredClone(answer);
  const onOpenSourceDocument = vi.fn(), onOpenFigure = vi.fn();
  const props = { selectedQueue: "", onSelectQueue: vi.fn(), onOpenFigure, ask: null, controls, onOpenSourceDocument };
  const view = render(<ConversationDrawer {...props} result={ready({ turns: [turn({ answer })], questions })} />);
  const check = () => {
    const list = view.container.querySelector(".conversation-answer-missing")!;
    const items = within(list as HTMLElement).getAllByRole("listitem");
    expect(items).toHaveLength(19);
    expect(items.slice(0, 6).map((item) => item.textContent)).toEqual(Array(6).fill("Some information for this answer is unavailable."));
    for (const missing of answer.missing.slice(6)) expect(within(list as HTMLElement).getByText(missing.label)).toBeVisible();
    expect(list).not.toHaveTextContent("selected_balances");
    expect(list).not.toHaveTextContent("no_compatible_evidence");
    expect(view.getByText(answer.gradeSentence)).toBeVisible();
    for (const figure of answer.figures) {
      const button = view.getByRole("button", { name: `${figure.written} ${figure.what}` });
      expect(button).toBeVisible();
      fireEvent.click(button);
      expect(onOpenFigure).toHaveBeenLastCalledWith(figure.evidenceId);
    }
    fireEvent.click(view.getByRole("button", { name: "Open source · page 1" }));
    const anchor = answer.sourceAssertions![0].anchors[0];
    expect(onOpenSourceDocument).toHaveBeenLastCalledWith(anchor.documentId, anchor.page);
  };
  check();
  view.rerender(<ConversationDrawer {...props} result={ready({ turns: [], questions })} />);
  view.rerender(<ConversationDrawer {...props} result={ready({ turns: [turn({ answer: structuredClone(saved) })], questions })} />);
  check();
  expect(answer).toStrictEqual(saved);
});

it("uses nonblank question then label then structural fallback for novel missing entries", () => {
  const answer = novel_answer;
  const view = render(<ConversationDrawer result={ready({ turns: [turn({ answer })], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={controls} />);
  const list = view.container.querySelector(".conversation-answer-missing")!;
  expect(within(list as HTMLElement).getAllByRole("listitem").map((item) => item.textContent)).toEqual([
    "Some information for this answer is unavailable.", "Some information for this answer is unavailable.",
    "Some information for this answer is unavailable.", "Readable uncertainty", "Which account did you mean?",
  ]);
});

it("uses the same fallback and precedence when suppressing missing copy already in the answer", () => {
  const answer = duplicate_answer;
  const view = render(<ConversationDrawer result={ready({ turns: [turn({ answer })], questions })} selectedQueue="" onSelectQueue={vi.fn()} onOpenFigure={openFigure} ask={null} controls={controls} />);
  const list = view.container.querySelector(".conversation-answer-missing")!;
  expect(within(list as HTMLElement).getAllByRole("listitem").map((item) => item.textContent)).toEqual(["A separate uncertainty"]);
});
